using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver (reflection-based)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Get strongly-typed metadata: JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind = {personInfo.Kind}");

// Prove it works — serialize using the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false if not resolvable
//    Use options that have NO resolver, so nothing can be resolved.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

bool found = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo for Person on empty resolver: found={found}, info={info?.Type.Name ?? "(null)"}");

// Compare: the same call succeeds on the full resolver
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo for Person on default resolver: found={found2}, info={info2?.Type.Name ?? "(null)"}");

// A resolver that resolves nothing
sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

record Person(string Name, int Age);

